import { createDocumentHandler } from "@/lib/artifacts/server";
import { encodeDocRef } from "@/lib/doc/ref";

/**
 * Documents are never generated by the model.
 *
 * A document is a file the user attached, so the streaming callbacks have
 * nothing to stream: they hand the client the descriptor and the studio does
 * the rest.
 */
export const docDocumentHandler = createDocumentHandler<"doc">({
  kind: "doc",
  onCreateDocument: ({ dataStream, title }) => {
    const content = encodeDocRef({ storageKey: "", title });

    dataStream.write({
      data: content,
      transient: true,
      type: "data-docDelta",
    });

    return Promise.resolve(content);
  },
  onUpdateDocument: ({ document, dataStream }) => {
    const content = document.content ?? encodeDocRef({ storageKey: "" });

    dataStream.write({
      data: content,
      transient: true,
      type: "data-docDelta",
    });

    return Promise.resolve(content);
  },
});
